  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "The closest high-transfer analogue, [18F]-(R)-TRACK, which shares the diethylacetamide and 4-fluoroethoxyphenyl motif, passed the BBB and showed high brain uptake in nonhuman primates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "PBR102, another close analogue with the same diethylacetamide and substituted-phenyl core, showed initial high brain uptake followed by fast clearance in nonhuman primate PET-CT, confirming CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "STS-E412, a pyrazolo[1,5-a]pyrimidine with the same dimethylpyrazolopyrimidine core, was permeable across the BBB in rats with a brain/plasma ratio of 0.39 after intraperitoneal dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Alpidem, a close imidazopyridine acetamide analogue, easily crosses the BBB in rats with a brain/plasma ratio of about 2.0-2.5 after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Zolpidem, a structurally related imidazopyridine acetamide, achieved meaningful central exposure after oral dosing in rats, with brain concentrations of 0.53 µM at 0.5 h.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Compound 40, a pyrazolopyrimidine analogue, crossed the BBB in mice and exhibited approximately 3-fold higher brain exposure than plasma.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A structurally distant nucleoside radiotracer showed negligible brain uptake, but its low similarity and different chemotype limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. The query is DPA-714, a well-characterized TSPO PET radiotracer. Multiple close structural analogues sharing the diethylacetamide and pyrazolo/imidazopyridine scaffolds demonstrate robust BBB penetration in vivo across nonhuman primate PET, rat brain/plasma, and mouse PK studies. The physicochemical prior is favorable, and the single impermeable analogue is structurally distant and does not override the consistent direct evidence.",
  "evidence_gaps": [
    "No direct human brain uptake data for the exact query molecule, though nonhuman primate and rodent data for close analogues are strong.",
    "Efflux transporter status was not directly measured for the query, but multiple close analogues with similar amide motifs show high brain uptake.",
    "Quantitative unbound brain-to-plasma ratio (Kp,uu) is not available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

